SELECT 'open' AS col, count(open) AS populated FROM market.daily_metrics UNION ALL SELECT 'high' AS col, count(high) AS populated FROM market.daily_metrics UNION ALL SELECT 'low' AS col, count(low) AS populated FROM market.daily_metrics UNION ALL SELECT 'aroon_up' AS col, count(aroon_up) AS populated FROM market.daily_metrics UNION ALL SELECT 'aroon_down' AS col, count(aroon_down) AS populated FROM market.daily_metrics UNION ALL SELECT 'pct_from_atl' AS col, count(pct_from_atl) AS populated FROM market.daily_metrics UNION ALL SELECT 'volume_avg_52w' AS col, count(volume_avg_52w) AS populated FROM market.daily_metrics UNION ALL SELECT 'return_5d' AS col, count(return_5d) AS populated FROM market.daily_metrics UNION ALL SELECT 'return_20d' AS col, count(return_20d) AS populated FROM market.daily_metrics UNION ALL SELECT 'return_60d' AS col, count(return_60d) AS populated FROM market.daily_metrics UNION ALL SELECT 'sma_5_prev' AS col, count(sma_5_prev) AS populated FROM market.daily_metrics UNION ALL SELECT 'sma_20_prev' AS col, count(sma_20_prev) AS populated FROM market.daily_metrics UNION ALL SELECT 'rsi_overbought' AS col, count(rsi_overbought) AS populated FROM market.daily_metrics UNION ALL SELECT 'rsi_oversold' AS col, count(rsi_oversold) AS populated FROM market.daily_metrics UNION ALL SELECT 'macd_bullish_cross' AS col, count(macd_bullish_cross) AS populated FROM market.daily_metrics UNION ALL SELECT 'macd_bearish_cross' AS col, count(macd_bearish_cross) AS populated FROM market.daily_metrics UNION ALL SELECT 'adl' AS col, count(adl) AS populated FROM market.daily_metrics ORDER BY populated DESC, col;
